def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    my_last, opp_last = history[-1]
    if n == 1:
        return 'D' if opp_last == 'D' else 'C'

    opp_c = 0
    my_c = 0
    for me, opp in history:
        if me == 'C':
            my_c += 1
        if opp == 'C':
            opp_c += 1

    recent8_c = 0
    start8 = n - (8 if n >= 8 else n)
    for i in range(start8, n):
        if history[i][1] == 'C':
            recent8_c += 1

    recent5_c = 0
    start5 = n - (5 if n >= 5 else n)
    for i in range(start5, n):
        if history[i][1] == 'C':
            recent5_c += 1

    opp_c_tail = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_c_tail += 1
        else:
            break

    tw = 8 if n - 1 >= 8 else n - 1
    recent_c_total = 0
    recent_c_to_d = 0
    recent_d_to_c = 0
    trans_start = n - 1 - tw
    for i in range(trans_start, n - 1):
        me = history[i][0]
        opp_next = history[i + 1][1]
        if me == 'C':
            recent_c_total += 1
            if opp_next == 'D':
                recent_c_to_d += 1
        else:
            if opp_next == 'C':
                recent_d_to_c += 1

    if opp_c == 0:
        return 'D'
    if recent5_c == 0 and opp_c * 4 < n:
        return 'D'
    if recent8_c <= 1 and opp_c * 4 < n:
        return 'D'
    if recent_c_total >= 3 and recent_c_to_d >= 3 and recent5_c <= 1:
        return 'D'

    if opp_last == 'C':
        high_coop = recent8_c >= 5 and recent5_c >= 4 and opp_c * 10 >= 8 * n
        if high_coop:
            if my_last == 'C':
                if recent_d_to_c >= 1:
                    return 'D'
                if (opp_c == n and my_c == n and opp_c_tail >= 15 and
                        recent_d_to_c == 0 and 30 <= n <= 85):
                    if rng.random() < 0.03:
                        return 'D'
            else:
                if recent_d_to_c >= 2:
                    return 'D'
            if my_last == 'D':
                return 'C'
        elif my_last == 'D':
            return 'C'

    if opp_last == 'D':
        if my_last == 'D':
            if opp_c * 3 >= n or recent8_c >= 1:
                return 'C'
            return 'D'
        if history[-2][0] == 'D':
            return 'C'
        return 'D'

    return 'C'
